import numpy as np
import statsmodels.tsa.statespace.dynamic_factor_mq as mod
from statsmodels.tools.sm_exceptions import ConvergenceWarning, EstimationWarning

def _get_small_em_model():
    rng = np.random.default_rng(0)
    nobs = 30
    k_endog = 2
    factor = np.cumsum(rng.standard_normal(nobs)) * 0.3
    endog = factor[:, None] * rng.uniform(0.6, 1.4, k_endog)[None, :]
    endog = endog + rng.standard_normal((nobs, k_endog)) * 0.5
    return mod.DynamicFactorMQ(endog, factors=1, factor_orders=1, idiosyncratic_ar1=False)
